import {
  PlaneGeometry,
  Group,
  Mesh,
  DirectionalLight,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  TextureLoader,
  RepeatWrapping,
  Vector2,
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  smoothstep,
  time,
  uniform,
  positionLocal,
  normalLocal,
  texture,
  displacement,
  float,
  mul,
  add,
  sub,
  clamp,
  sin,
  cos,
  vec2,
  Fn,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  // --- Backdrop plane (stage) ---
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  // Create a gradient material using TSL
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = Fn(() => {
    const vUv = uv();
    // Vertical gradient from surface (top) to ink (bottom)
    const colorA = vec3(0.043, 0.043, 0.063); // #0b0b10
    const colorB = vec3(0.086, 0.086, 0.118); // #16161d
    const mixed = mix(colorA, colorB, vUv.y);
    return mixed;
  })();
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.name = 'backdrop';

  // --- Main parallax plane ---
  const group = new Group();
  group.name = 'pricing-row';

  // Create tessellated plane geometry
  const segments = 64;
  const geo = new PlaneGeometry(2.5, 0.8, segments, segments); // size based on typical row width/height
  // We'll adjust size later? The spec says "List row for Pricing: a horizontal row". We'll use width 2.5, height 0.8.

  // Create material with displacement
  const mat = new MeshStandardNodeMaterial();
  mat.color = new THREE.Color(paper); // fallback color
  mat.roughness = 0.5;
  mat.metalness = 0.55;
  mat.clearcoat = 0.25;

  // Create placeholder textures (1x1 white)
  const placeholderTex = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
  placeholderTex.needsUpdate = true;
  mat.map = placeholderTex;
  mat.displacementMap = placeholderTex;
  mat.displacementScale = 0.1; // subtle displacement

  // Load actual textures
  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      tex.repeat.set(1, 1);
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }
  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      tex.repeat.set(1, 1);
      mat.displacementMap = tex;
      mat.needsUpdate = true;
    });
  }

  // Create displacement node using TSL
  // We'll use the displacementMap and scale
  const dispMap = texture(mat.displacementMap, uv());
  const dispScale = uniform(0.1);
  const dispOffset = uniform(0.0);
  const dispValue = add(mul(dispMap, dispScale), dispOffset);
  // Apply displacement along normal
  const displacedPos = add(positionLocal, mul(normalLocal, dispValue));
  // We need to set the positionNode on the material? Actually for displacement we need to use the displacement node on the geometry? In TSL, we can set the positionNode on the material's vertex shader. But MeshStandardNodeMaterial has a positionNode property. We'll set it.
  mat.positionNode = displacedPos;

  // Create mesh
  const mesh = new Mesh(geo, mat);
  mesh.name = 'parallax-plane';
  group.add(mesh);

  // --- Rim light (accent) ---
  const rimLight = new DirectionalLight(accent, 0.8);
  rimLight.position.set(-2, 1, 3); // behind and to the left
  group.add(rimLight);

  // --- Add a subtle key light from front-right ---
  const keyLight = new DirectionalLight(paper, 0.6);
  keyLight.position.set(2, 1, 2);
  group.add(keyLight);

  // --- Add ambient fill (already provided by scene, but we can add a small one) ---
  const ambient = new THREE.AmbientLight(surface, 0.3);
  group.add(ambient);

  // --- Add contact shadow plane (optional, but spec says grounded objects get a radial contact-shadow plane) ---
  // Since this is a row, it's not grounded? But we can add a subtle shadow below.
  const shadowGeo = new THREE.PlaneGeometry(2.8, 1.0);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = Fn(() => {
    const vUv = uv();
    const dist = length(sub(vUv, vec2(0.5, 0.5)));
    const alpha = smoothstep(0.5, 0.0, dist); // radial falloff
    return vec3(0, 0, 0, mul(alpha, 0.4)); // opacity 0.4
  })();
  shadowMat.transparent = true;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.01; // slightly behind
  shadow.position.y = -0.4; // below the row
  group.add(shadow);

  // --- Apply cinematic primitives ---
  const primitiveCleanups = [];
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    const result = ctx.primitives[p.name](group, p.params);
    if (result && result.cleanup) {
      primitiveCleanups.push(result.cleanup);
    }
  }

  // --- Interactions ---
  const handlers = {};
  // Hover: rise-in preset (subtle, 0.15 scene units)
  let hoverTween = null;
  handlers.onPointerEnter = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: 0.15,
      duration: 0.3,
      ease: 'power2.out',
    });
  };
  handlers.onPointerLeave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: 0,
      duration: 0.3,
      ease: 'power2.out',
    });
  };
  handlers.onClick = () => {
    ctx.emit('hub-pricing.select', {});
  };

  // --- Cleanup ---
  const cleanup = () => {
    // Kill GSAP tweens
    if (hoverTween) hoverTween.kill();
    // Dispose geometry and material
    geo.dispose();
    mat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    // Dispose textures
    if (mat.map) mat.map.dispose();
    if (mat.displacementMap) mat.displacementMap.dispose();
    // Call primitive cleanups
    primitiveCleanups.forEach(fn => fn());
  };

  // Assemble node
  const node = new Group();
  node.add(backdrop);
  node.add(group);
  node.userData.handlers = handlers;
  node.userData.cleanup = cleanup;

  return node;
}
